"""Build a review page from measured candidates and real production Godot renders."""
from pathlib import Path
import hashlib
import html
import json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'doc/book/iterations/2026-09-16-folded-strip-research'


def build():
    data = json.loads((OUT / 'selected-cases.json').read_text())
    report = json.loads((OUT / 'render-report.json').read_text())
    assert not report['failures'], report['failures']
    assert report['source_unchanged']
    assert report['cases_sha256'] == hashlib.sha256((OUT / 'selected-cases.json').read_bytes()).hexdigest()
    assert len(report['rows']) == len(data['cases']) * 8
    for row in report['rows']:
        assert row['geometry_unchanged']
        assert hashlib.sha256((OUT / row['image']).read_bytes()).hexdigest() == row['sha256']
    modes = {'facet': 'Facets', 'cast': 'Cast', 'armature': 'Edges', 'shell': 'Thick triangles'}
    descriptions = {
        'shipped': ('The starting surface', 'It looks articulated, but all its vertices lie in one plane. Alternating colours and lighting can suggest folds that the coordinates do not contain.'),
        'hinge-single-70': ('One decision changes the whole strip', 'Turn everything beyond one shared edge. Each triangle keeps its shape, but half the strip now occupies another plane. This is the clearest first encounter.'),
        'hinge-paired-40': ('A repeated decision becomes a body', 'Pair the signs of successive hinge turns. The same strip rises into a pleated form. This is the strongest candidate here for developing the existing artifact.'),
        'bend-180': ('A curve made from straight faces', 'Bend the sampled strip around a semicircle. Its silhouette becomes broad and curved; its individual faces remain triangles. The finite mesh changes edge lengths slightly.'),
        'twist-360': ('Turn while moving along', 'Rotate successive cross-sections around the long axis. The familiar ribbon appears, but the distance between connected vertices changes. This is deformation, rather than rigid folding.'),
        'wave-1-050': ('Let sine enter the surface', 'A half-metre wave displaces the strip. An already familiar operation gives the surface another rhythm, while stretching some edges by more than a quarter.'),
        'hinge-alternating-60': ('A rule can preserve lengths and still fail', 'This repeated fold compacts the strip into a small knot. The ideal faces cross one another. Keeping every triangle intact is insufficient to make a physically foldable object.'),
        'collapsed': ('The triangles are still listed', 'Put all the vertices on one line. The source still lists 24 triangle connections, but none encloses area. The edge treatment can remain visible because its tubes have their own thickness.'),
    }
    order = list(descriptions)
    cases = {c['id']: c for c in data['cases']}
    cards = []
    for index, cid in enumerate(order):
        c = cases[cid]
        m = c['metrics']
        failed = cid in ('hinge-alternating-60', 'collapsed')
        category = 'limits' if failed else 'folds' if c['family'].startswith('hinge') else 'deformations' if cid != 'shipped' else 'baseline'
        title, prose = descriptions[cid]
        crease = 'Undefined' if m['max_crease_degrees'] is None else f"{m['max_crease_degrees']:.1f}°"
        drift = '< 0.001 mm' if 0 < m['max_edge_length_drift_m'] < .000001 else f"{1000*m['max_edge_length_drift_m']:.2f} mm"
        contacts = 'Not evaluated: no area' if m['degenerate_triangles'] else str(m['disjoint_triangle_intersection_count'])
        imgs = ''.join(f'''<figure><button class="image-button" data-case="{cid}" data-mode="{mode}" aria-label="Enlarge {html.escape(c['title'])}: {label}"><img src="triangle-strip-research/renders/{cid}-{mode}-oblique.png" width="960" height="640" loading="lazy" alt="Godot render of {html.escape(c['title'])}, {label}, oblique view"></button><figcaption>{label}{' · shading issue' if mode == 'cast' else ''}</figcaption></figure>''' for mode, label in modes.items())
        cards.append(f'''<article id="{cid}" class="case" data-category="{category}">
          <div class="case-heading"><span class="number">{index+1:02}</span><div><p class="eyebrow">{html.escape(c['title'])} · {'retained failure' if failed else category}</p><h2>{title}</h2><p>{prose}</p></div><a class="permalink" href="#{cid}" aria-label="Link to {html.escape(c['title'])}">↗</a></div>
          <div class="images">{imgs}</div>
          <dl class="metrics"><div><dt>Largest crease</dt><dd>{crease}</dd></div><div><dt>Largest edge change</dt><dd>{drift} <small>({100*m['max_edge_length_drift_ratio']:.2f}%)</small></dd></div><div><dt>Disjoint face contacts</dt><dd>{contacts}</dd></div><div><dt>Zero-area faces</dt><dd>{len(m['degenerate_triangles'])} / 24</dd></div></dl>
          <details><summary>Why this case · parameters · measurements</summary><p>{html.escape(c['selection_reason'])}</p><pre>{html.escape(json.dumps(c['parameters'], indent=2))}</pre><p>Local extents: {' × '.join(f'{v:.3f}' for v in m['extent_m'])} m. Minimum triangle area: {m['min_triangle_area_m2']:.6f} m². Measurements concern the original ideal surface, before tubes or thickness are added.</p></details>
        </article>''')
    page = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>24 triangles · Folded strip research · Ada</title>
<style>
:root{--ink:#242b26;--muted:#59655e;--paper:#f4f1e9;--green:#245d41;--line:#c8cdc0}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:105px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,sans-serif}a{color:var(--green);text-underline-offset:4px}button,select{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #b25741;outline-offset:4px}header,main,footer{max-width:1440px;margin:auto;padding:24px 4vw}.nav{display:flex;justify-content:space-between;gap:20px;font-size:13px;border-bottom:1px solid var(--line);padding-bottom:16px}.eyebrow{text-transform:uppercase;font-size:11px;letter-spacing:.12em;color:var(--muted);font-weight:650}.intro{display:grid;grid-template-columns:1fr 1.15fr;gap:36px;align-items:center;padding:38px 0 12px}.intro h1{font:clamp(38px,4.6vw,68px)/1.06 Georgia,serif;letter-spacing:-.035em;margin:12px 0 22px}.intro p{max-width:540px}.intro figure{margin:0}.intro img{width:100%;height:auto;border-radius:3px}.intro figcaption{font-size:12px;color:var(--muted);padding-top:8px}.stats{display:flex;gap:24px;flex-wrap:wrap;margin:26px 0 12px}.stats strong{font:30px Georgia,serif;display:block}.stats span{font-size:12px;color:var(--muted)}.note{border-left:3px solid var(--green);padding:4px 20px;margin:26px 0 8px;max-width:1020px}.note p{margin:8px 0}.toolbar{position:sticky;top:0;z-index:3;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:15px 4vw;background:#f4f1e9f5;backdrop-filter:blur(8px);border-block:1px solid var(--line)}.toolbar-inner{max-width:1325px;margin:auto;display:flex;width:100%;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}.view{display:flex;gap:6px}.view button,.toolbar select{padding:8px 12px;border:1px solid var(--line);border-radius:3px;background:transparent;font-size:13px}.view button[aria-pressed=true]{background:var(--green);color:white;border-color:var(--green)}.filter-label{font-size:12px}.count{font-size:12px;color:var(--muted)}.case{border-bottom:1px solid var(--line);padding:35px 0}.case[hidden]{display:none}.case-heading{display:flex;gap:22px;max-width:1040px;align-items:flex-start}.number{font:28px Georgia,serif;color:#94a28e;padding-top:6px}.case-heading .eyebrow{margin:0 0 6px}.case h2{font:28px/1.2 Georgia,serif;letter-spacing:-.015em;margin:4px 0 12px}.case-heading p{max-width:810px;margin:0 0 15px}.permalink{text-decoration:none;font-size:25px;margin-left:auto}.images{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:12px}.images figure{margin:0}.image-button{display:block;border:0;padding:0;background:#e9e7df;width:100%;border-radius:3px;overflow:hidden}.image-button img{width:100%;height:auto;display:block;transition:filter .15s}.image-button:hover img{filter:brightness(.96)}figcaption{font-size:12px;padding:8px 0;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.metrics dt{font-size:11px;color:var(--muted)}.metrics dd{margin:4px 0;font-size:16px}.metrics small{font-size:11px;color:var(--muted)}details{font-size:13px;color:var(--muted)}summary{cursor:pointer}pre{white-space:pre-wrap;max-height:220px;overflow:auto;background:#e8e9df;padding:14px}.method{max-width:950px;padding:35px 0}.method h2{font:32px Georgia,serif}.method li{margin:12px 0}.next{background:#e3e8da;padding:24px 30px;border-radius:3px;margin:25px 0}.next h3{font:25px Georgia,serif;margin:0}.next p{margin-bottom:0}.links{display:flex;flex-wrap:wrap;gap:10px 24px;font-size:13px}footer{font-size:12px;color:var(--muted);padding-bottom:50px}dialog{border:1px solid var(--line);border-radius:6px;background:var(--paper);max-width:min(1100px,96vw);max-height:96vh;padding:15px}dialog::backdrop{background:#102019b8}dialog img{display:block;max-width:100%;max-height:78vh;object-fit:contain;margin:auto}dialog .dialog-top{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:0 0 10px;font-size:14px}dialog button{border:1px solid var(--line);background:transparent;padding:5px 12px;border-radius:3px}@media(max-width:850px){.intro{grid-template-columns:1fr;gap:15px}.intro h1{max-width:650px}.images{grid-template-columns:repeat(2,1fr)}.metrics{grid-template-columns:repeat(2,1fr)}.intro figure{max-width:650px}.case h2{font-size:25px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.image-button img{transition:none}}
</style></head><body>
<header><nav class="nav"><a href="/research/possible-bodies/">Ada Research · Possible bodies</a><a href="/long-museum/encounters?map=Point_Triangle_Context">Triangle hall encounters ↗</a></nav>
<section class="intro"><div><p class="eyebrow">A bounded study · 16 September 2026</p><h1>24 triangles.<br>What can this<br>strip become?</h1><p>The triangle hall already contains <code>folded_strip</code>. We kept its 26 vertices and their connections, then searched for forms hidden in that modest starting point.</p><p>These are real Godot renders through the existing artifact code. The hall and the book remain unchanged while we look.</p><div class="stats"><div><strong>47</strong><span>measured candidates</span></div><div><strong>8</strong><span>contrasts to examine</span></div><div><strong>4</strong><span>existing treatments</span></div><div><strong>64</strong><span>Godot captures</span></div></div></div><figure><img src="triangle-strip-research/renders/hinge-paired-40-shell-oblique.png" width="960" height="640" alt="Paired folds rendered as separate thickened triangles on a research plinth"><figcaption>Paired 40° hinge turns · thick triangles · research stage, outside the museum.</figcaption></figure></section>
<aside class="note"><p><strong>What the study found.</strong> The starting strip is flat. Real hinges can make it rise without stretching its triangles. Repeating a fold can also send faces through one another. Meanwhile, the renderer can make a flat surface appear creased.</p><p>Use the second view to check what the first image suggests. Click any image to enlarge it.</p></aside></header>
<div class="toolbar"><div class="toolbar-inner"><div class="view" role="group" aria-label="Camera view"><button data-view="oblique" aria-pressed="true">Oblique view</button><button data-view="side" aria-pressed="false">Near-edge view</button></div><label class="filter-label">Show <select id="family" aria-label="Filter cases"><option value="all">All cases</option><option value="baseline">Starting surface</option><option value="folds">Rigid folds</option><option value="deformations">Deformations</option><option value="limits">Limits and failures</option></select></label><span id="count" class="count" aria-live="polite">8 cases · same scale</span></div></div>
<main>__CARDS__
<section class="method"><p class="eyebrow">Reading the evidence</p><h2>Same source strip. Different things made visible.</h2><ul>
<li><strong>Facets:</strong> the production red and green double-sided triangles. Its duplicated front and back faces can affect lighting.</li>
<li><strong>Cast:</strong> a single-colour surface with generated normals. The source uses alternating triangle winding without correcting it before smoothing. The flat control already shows a lighting pattern; do not read that pattern as a geometric fold.</li>
<li><strong>Edges:</strong> unshaded tubes, 12 mm in radius. They add geometry and stay bright regardless of lighting. Their brightness and thickness are part of this treatment.</li>
<li><strong>Thick triangles:</strong> each face becomes a separate 60 mm prism. This adds internal rims and can introduce overlaps. It is not a welded or watertight shell.</li>
</ul><p>All candidates retain the original surface connectivity. Folding changes its placement in space; this study does not establish a new abstract topology. The two failure cases show why connectivity alone cannot guarantee a usable surface.</p>
<details><summary>Measurement and capture method</summary><p>The default vertices were exported by Godot from the production script. A deterministic Python search generated the candidates and checked 18 analytic fixtures. Hinge candidates rotate downstream vertices around shared edges; bend, twist and wave candidates deform the sampled coordinates.</p><p>Creases use consistently oriented triangle normals, correcting strip parity for measurement only. Intersection counts concern zero-thickness faces with no shared vertex. Shared-vertex pairs, shell thickness and handle clearance are excluded; zero detected contacts is not a collision-free guarantee. Fully degenerate faces have undefined creases and are excluded from intersection tests.</p><p>Each candidate is translated onto the same plinth, without scaling. Every treatment uses the same two orthographic cameras, 6.2 m camera width, lights, 960 × 640 image size and Godot compatibility renderer. Grab handles are hidden and their processing is disabled to isolate the surface. The lowest ideal vertex is held 40 mm above the plinth so the added tubes and triangle thickness are not clipped. Original positions and production source hashes are checked during capture. These are isolated research-stage renders, not screenshots from the hall. There has been no headset or interaction test.</p></details>
<div class="next"><h3>My next candidate: the paired fold</h3><p>The single hinge makes the operation legible; the paired fold gives that operation a more surprising body. A useful next pass would repair the winding and normals, then let this existing strip slowly unfold and refold through those two cases. The gallery keeps the current rendering defects visible so we can distinguish a form decision from an engine repair.</p></div>
<div class="links"><a href="triangle-strip-research/all-cases.json">All 47 measured cases</a><a href="triangle-strip-research/selected-cases.json">Selection and analytic checks</a><a href="triangle-strip-research/render-report.json">Capture manifest and image hashes</a><a href="triangle-strip-research/README.md">Reproduce the study</a></div></section></main>
<footer>Research proposal, not a hall revision. The shortlist is selected for useful contrasts; the measurements do not rank beauty or decide what belongs in the book.</footer>
<dialog id="zoom" aria-labelledby="zoom-title"><div class="dialog-top"><span id="zoom-title"></span><button id="close">Close</button></div><img id="zoom-image" alt=""></dialog>
<script>
let view='oblique';const names={facet:'Facets',cast:'Cast',armature:'Edges',shell:'Thick triangles'};
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('.image-button').forEach(b=>{const img=b.querySelector('img');img.src=`triangle-strip-research/renders/${b.dataset.case}-${b.dataset.mode}-${view}.png`;img.alt=`Godot render of ${b.dataset.case}, ${names[b.dataset.mode]}, ${view==='side'?'near-edge':'oblique'} view`;});}));
document.getElementById('family').addEventListener('change',event=>{let count=0;document.querySelectorAll('.case').forEach(c=>{c.hidden=event.target.value!=='all'&&c.dataset.category!==event.target.value;if(!c.hidden)count++;});document.getElementById('count').textContent=`${count} ${count===1?'case':'cases'} · same scale`;});
const modal=document.getElementById('zoom');document.querySelectorAll('.image-button').forEach(b=>b.addEventListener('click',()=>{const img=b.querySelector('img');document.getElementById('zoom-title').textContent=b.closest('.case').querySelector('h2').textContent+' · '+names[b.dataset.mode]+' · '+(view==='side'?'near-edge':'oblique');document.getElementById('zoom-image').src=img.src;document.getElementById('zoom-image').alt=img.alt;modal.showModal();}));document.getElementById('close').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
</script></body></html>'''
    target = OUT / 'triangle-strip-research.html'
    target.write_text(page.replace('__CARDS__', '\n'.join(cards)), encoding='utf-8')
    print(f'Built {target}: {len(cases)} cases, {len(report["rows"])} verified captures')


if __name__ == '__main__':
    build()
